'use strict';

// MODULES //

var startsWith = require( '@stdlib/string/starts-with' );
var repeat = require( '@stdlib/string/repeat' );
var collapseContinuations = require( './collapse_continuations.js' );


// MAIN //

/**
* Un-wraps text by stripping a leading indent and collapsing continuation lines.
*
* @private
* @param {string} text - indented text
* @param {NonNegativeInteger} indent - number of leading spaces to strip
* @returns {string} un-wrapped text
*/
function unwrap( text, indent ) {
	var prefix;
	var lines;
	var i;

	prefix = repeat( ' ', indent );
	lines = text.split( '\n' );
	for ( i = 0; i < lines.length; i++ ) {
		if ( startsWith( lines[ i ], prefix ) ) {
			lines[ i ] = lines[ i ].substring( indent );
		}
	}
	return collapseContinuations( lines.join( '\n' ) );
}


// EXPORTS //

module.exports = unwrap;
